package dev.pact.app

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import dev.pact.app.core.Themes

/**
 * Android can't rename or recolor a launcher icon at runtime, so the manifest declares
 * one activity-alias per (name, theme) and exactly one is enabled. The aliases are
 * generated by scripts/gen_res.py; labels live in strings.xml.
 */
object LauncherNames {
    val names = listOf("Pact", "ToDo", "Tasks", "To-do list", "Checklist", "Reminders")

    private fun alias(context: Context, name: String, theme: String) =
        ComponentName(context.packageName, "dev.pact.app.L_" + name.filter { it.isLetterOrDigit() } + "_" + theme)

    /** Enables the launcher entry for [name] in [theme]'s colors, if it isn't already. */
    fun apply(context: Context, name: String, theme: String) {
        val pm = context.packageManager
        val themes = Themes.all(context).map { it.id }
        val chosen = alias(context, if (name in names) name else names.first(), if (theme in themes) theme else themes.first())
        if (pm.getComponentEnabledSetting(chosen) == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) return
        // Enable the new entry first so the app always has a launcher icon.
        pm.setComponentEnabledSetting(chosen, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
        for (n in names) for (t in themes) {
            val c = alias(context, n, t)
            if (c != chosen) pm.setComponentEnabledSetting(c, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
        }
    }
}
